const K={expenses:'spendly-expenses-v1',budget:'spendly-monthly-budget-v1',categories:'spendly-categories-v1',categoryBudgets:'spendly-category-budgets-v1',recurring:'spendly-recurring-v1',goals:'spendly-goals-v1',prefs:'spendly-preferences-v1'};
const $=id=>document.getElementById(id),money=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0});
const initialCats=[['Food','🍜'],['Travel','🚕'],['Rent','🏠'],['Shopping','🛍️'],['Bills','⚡'],['Other','✨']].map(([name,icon])=>({name,icon}));
let expenses=JSON.parse(localStorage.getItem(K.expenses)||'[]'),categories=JSON.parse(localStorage.getItem(K.categories)||'null')||initialCats,budget=+localStorage.getItem(K.budget)||30000,catBudgets=JSON.parse(localStorage.getItem(K.categoryBudgets)||'{}'),recurring=JSON.parse(localStorage.getItem(K.recurring)||'[]'),goals=JSON.parse(localStorage.getItem(K.goals)||'[]'),prefs=JSON.parse(localStorage.getItem(K.prefs)||'{}');
let range='week',filter='All',query='',chosenCategory='Food',entryType='expense',editingId=null,visibleCount=5,customStart='',customEnd='',cloudBackupTimer;
