const icon=n=>categories.find(c=>c.name===n)?.icon||'✨',esc=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function bounds(type){const n=new Date();n.setHours(0,0,0,0);if(type==='week'){const s=new Date(n);s.setDate(n.getDate()-((n.getDay()+6)%7));return[s,n]}if(type==='month')return[new Date(n.getFullYear(),n.getMonth(),1),n];if(type==='custom'){const start=customStart?new Date(`${customStart}T00:00:00`):new Date(n.getFullYear(),n.getMonth(),1),end=customEnd?new Date(`${customEnd}T00:00:00`):n;return[start,end]}return[new Date(n.getFullYear(),n.getMonth()-1,1),new Date(n.getFullYear(),n.getMonth(),0)]}
function inside(x,type){const[s,e]=bounds(type),d=new Date(`${x.date}T00:00:00`);return d>=s&&d<=e}function matches(x){return(filter==='All'||x.category===filter)&&(!query||`${x.category} ${x.note||''} ${x.payment||''}`.toLowerCase().includes(query))}
function allFor(type){return expenses.filter(x=>inside(x,type)&&matches(x))}function total(a,type){return a.filter(x=>(x.type||'expense')===type).reduce((s,x)=>s+ +x.amount,0)}
function renderCategoryControls(){if(!categories.some(c=>c.name===chosenCategory))chosenCategory=categories[0]?.name||'';if(filter!=='All'&&!categories.some(c=>c.name===filter))filter='All';$('category-picker').innerHTML=categories.map(c=>`<button type="button" data-cat="${esc(c.name)}" class="${c.name===chosenCategory?'chosen':''}">${c.icon}<span>${esc(c.name)}</span></button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{chosenCategory=b.dataset.cat;renderCategoryControls()});$('category-filter').innerHTML=`<option value="All">All categories</option>${categories.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('')}`;$('category-filter').value=filter;renderCategoryList()}
function chartData(){const[s,e]=bounds(range),days=[];for(let d=new Date(s);d<=e;d.setDate(d.getDate()+1)){const day=d.getDate(),key=localKey(d);days.push({date:new Date(d),label:range==='week'?d.toLocaleDateString('en',{weekday:'short'}).slice(0,1):(day===1||day%5===0||+d===+e?day:''),total:total(expenses.filter(x=>x.date===key&&matches(x)),'expense')})}if(days.length<=14)return days;const grouped=[];for(let i=0;i<days.length;i+=7){const group=days.slice(i,i+7),first=group[0].date,last=group[group.length-1].date;grouped.push({label:`${first.getDate()}–${last.getDate()}`,total:group.reduce((sum,item)=>sum+item.total,0)})}return grouped}
function renderChart(){const data=chartData(),max=Math.max(1,...data.map(x=>x.total));$('chart').innerHTML=data.map(x=>`<div class="bar-wrap"><span class="bar-value">${x.total?fmt(x.total):''}</span><span class="bar" style="height:${Math.max(3,x.total/max*76)}px"></span><span class="bar-label">${x.label}</span></div>`).join('')}
function renderBreakdown(items){const groups={};items.filter(x=>(x.type||'expense')==='expense').forEach(x=>groups[x.category]=(groups[x.category]||0)+ +x.amount);const max=Math.max(1,...Object.values(groups));$('breakdown').innerHTML=Object.entries(groups).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([n,v])=>{const limit=catBudgets[n],percent=limit?v/limit*100:v/max*100;return`<div class="breakdown-row ${limit&&percent>100?'over-budget':''}"><span>${icon(n)} ${esc(n)}</span><i style="--percent:${Math.min(percent,100)}%"></i><b>${fmt(v)}${limit?` / ${fmt(limit)} · ${Math.round(percent)}%`:''}</b></div>`}).join('')||'<small>No expense data for this period.</small>'}
function insight(items){const spend=total(items,'expense');if(!spend)return'Add expenses to receive smarter insights.';const groups={};items.filter(x=>(x.type||'expense')==='expense').forEach(x=>groups[x.category]=(groups[x.category]||0)+ +x.amount);const [name,value]=Object.entries(groups).sort((a,b)=>b[1]-a[1])[0];return `${name} is your biggest expense at ${fmt(value)} — ${Math.round(value/spend*100)}% of spending in this period.`}
function render(){const items=allFor(range).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt),month=allFor('month'),spend=total(items,'expense'),income=total(items,'income'),monthSpend=total(month,'expense');$('month-total').textContent=fmt(monthSpend);$('budget-label').textContent=fmt(budget);$('budget-progress').style.width=Math.min(100,monthSpend/budget*100)+'%';$('month-trend').textContent=monthSpend?`${Math.round(monthSpend/budget*100)}% budget`:'On track';$('range-total').textContent=fmt(spend);$('range-count').textContent=items.length;$('range-income').textContent=fmt(income);$('range-saved').textContent=fmt(income-spend);$('overview-caption').textContent=range==='week'?'Monday through today':range==='month'?'Your current month':'Previous calendar month';$('chart-subtitle').textContent=`Daily spending ${range==='week'?'this week':range==='month'?'this month':'last month'}`;$('insight-text').textContent=insight(items);renderChart();renderBreakdown(items);const visible=items.slice(0,visibleCount),t=$('transaction-template');$('transactions').innerHTML='';visible.forEach(x=>{const n=t.content.cloneNode(true);n.querySelector('.category-icon').textContent=(x.type||'expense')==='income'?'↑':icon(x.category);n.querySelector('.transaction-info strong').textContent=x.note||x.category;n.querySelector('.transaction-info small').textContent=`${x.type==='income'?'Income':'Expense'} · ${x.category} · ${new Date(`${x.date}T00:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}`;n.querySelector('b').textContent=`${x.type==='income'?'+':'−'}${fmt(x.amount)}`;n.querySelector('.edit-expense').onclick=()=>openEntry(x.id);$('transactions').append(n)});$('empty-state').classList.toggle('hidden',visible.length>0);$('see-all').textContent=items.length>visible.length?'Load more ↓':''}
function modal(id,on=true){$('modal-backdrop').classList.toggle('hidden',!on);$(id).classList.toggle('hidden',!on)}function closeAll(){['expense-modal','budget-modal','category-modal','tools-modal','tool-detail'].forEach(id=>$(id).classList.add('hidden'));$('modal-backdrop').classList.add('hidden')}
function setType(type){entryType=type;document.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===type));$('category-entry').classList.toggle('hidden',type==='income')}
function openEntry(id){editingId=id;const x=id&&expenses.find(v=>v.id===id);$('expense-form').reset();if(x){entryType=x.type||'expense';chosenCategory=x.category;$('amount').value=x.amount;$('note').value=x.note||'';$('expense-date').value=x.date;$('payment-method').value=x.payment||'UPI';$('modal-title').textContent='Edit transaction';$('save-expense').textContent='Update transaction';$('delete-expense').classList.remove('hidden')}else{editingId=null;entryType='expense';chosenCategory=categories[0]?.name||'';$('expense-date').value=localKey(new Date());$('modal-title').textContent='Add transaction';$('save-expense').textContent='Save transaction';$('delete-expense').classList.add('hidden')}setType(entryType);renderCategoryControls();modal('expense-modal')}
function renderCategoryList(){$('category-list').innerHTML=categories.map(c=>`<div class="category-row"><span>${c.icon}</span><strong>${esc(c.name)}</strong><button data-rename="${esc(c.name)}">Edit</button><button class="delete-category" data-remove="${esc(c.name)}">Delete</button></div>`).join('');document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>renameCat(b.dataset.rename));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeCat(b.dataset.remove))}
function renameCat(old){const name=prompt('Rename category',old)?.trim().replace(/[^a-zA-Z0-9 &-]/g,'');if(!name||name===old)return;if(categories.some(c=>c.name.toLowerCase()===name.toLowerCase()))return alert('That category already exists.');categories=categories.map(c=>c.name===old?{...c,name}:c);expenses=expenses.map(x=>x.category===old?{...x,category:name}:x);if(chosenCategory===old)chosenCategory=name;if(filter===old)filter=name;save(K.categories,categories);save(K.expenses,expenses);renderCategoryControls();render()}
