function detail(title,html){$('detail-title').textContent=title;$('detail-content').innerHTML=html;modal('tool-detail');setTimeout(injectFingerprintControl,0)}
function showBudgets(){detail('Category budgets',`<div class="detail-section"><h3>Set monthly limits</h3>${categories.map(c=>`<label>${c.icon} ${esc(c.name)}<input data-cat-budget="${esc(c.name)}" type="number" min="0" placeholder="No limit" value="${catBudgets[c.name]||''}"></label>`).join('')}<button class="detail-add" id="save-cat-budgets">Save category budgets</button></div>`);$('save-cat-budgets').onclick=()=>{document.querySelectorAll('[data-cat-budget]').forEach(i=>{const v=+i.value;if(v)catBudgets[i.dataset.catBudget]=v;else delete catBudgets[i.dataset.catBudget]});save(K.categoryBudgets,catBudgets);closeAll();render()}}
function showRecurring(){detail('Recurring expenses',`<div class="detail-section"><button class="detail-add" id="add-recurring">+ Add recurring item</button>${recurring.map(r=>`<div class="detail-row"><span>${icon(r.category)}</span><strong>${esc(r.note||r.category)}<small>${fmt(r.amount)} · day ${r.day}</small></strong><button class="danger" data-del-rec="${r.id}">Delete</button></div>`).join('')||'<small>No recurring items yet.</small>'}</div>`);$('add-recurring').onclick=()=>{const note=prompt('Name (e.g. House rent)')?.trim();const amount=+prompt('Amount');const day=+prompt('Day of month (1–28)','1');if(!note||!amount||day<1||day>28)return;recurring.push({id:crypto.randomUUID(),note,amount,day,category:chosenCategory||categories[0].name});save(K.recurring,recurring);showRecurring()};document.querySelectorAll('[data-del-rec]').forEach(b=>b.onclick=()=>{recurring=recurring.filter(r=>r.id!==b.dataset.delRec);save(K.recurring,recurring);showRecurring()})}
