function showData(){detail('Export & backup','<div class="detail-section"><button class="pref-button" id="export-data">Download backup (.json)</button><button class="pref-button" id="import-data">Import backup</button><small>Imports replace all current local data.</small></div>');$('export-data').onclick=()=>{const blob=new Blob([JSON.stringify({expenses,categories,budget,catBudgets,recurring,goals,prefs},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='spendly-backup.json';a.click();URL.revokeObjectURL(a.href)};$('import-data').onclick=()=>$('import-file').click()}
function showPrefs(){const theme=prefs.theme||'#7255e8';detail('Preferences',`<div class="detail-section"><label>Theme color <input id="theme-color" type="color" value="${theme}"></label><div class="theme-presets"><button data-theme="#7255e8" style="background:#7255e8"></button><button data-theme="#147dca" style="background:#147dca"></button><button data-theme="#14946b" style="background:#14946b"></button><button data-theme="#dc5a79" style="background:#dc5a79"></button><button data-theme="#df7a24" style="background:#df7a24"></button></div><button class="pref-button" id="dark-toggle">${prefs.dark?'☀ Use light mode':'◐ Use dark mode'}</button><button class="pref-button" id="reminder-toggle">${prefs.reminder?'✓ Daily reminder enabled':'♧ Enable daily reminder'}</button><button class="pref-button" id="pin-toggle">${prefs.pin?'Change / remove PIN':'Set app PIN'}</button></div>`);const setTheme=value=>{prefs.theme=value;applyPrefs();save(K.prefs,prefs)};$('theme-color').oninput=e=>setTheme(e.target.value);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{setTheme(b.dataset.theme);$('theme-color').value=b.dataset.theme});$('dark-toggle').onclick=()=>{prefs.dark=!prefs.dark;applyPrefs();showPrefs()};$('reminder-toggle').onclick=async()=>{if(!('Notification'in window))return alert('Notifications are not supported by this browser.');if(Notification.permission==='default')await Notification.requestPermission();prefs.reminder=Notification.permission==='granted';save(K.prefs,prefs);showPrefs()};$('pin-toggle').onclick=()=>setPin()}
function shade(hex,amount){const n=parseInt(hex.slice(1),16),clamp=v=>Math.min(255,Math.max(0,v)),r=clamp((n>>16)+amount),g=clamp(((n>>8)&255)+amount),b=clamp((n&255)+amount);return`#${(r<<16|g<<8|b).toString(16).padStart(6,'0')}`}function applyPrefs(){const theme=prefs.theme||'#7255e8',root=document.documentElement;root.style.setProperty('--purple',theme);root.style.setProperty('--purple-deep',shade(theme,-28));root.style.setProperty('--theme-light',shade(theme,24));document.body.classList.toggle('dark',!!prefs.dark);save(K.prefs,prefs)}function setPin(){if(prefs.pin&&confirm('Remove your current PIN?')){delete prefs.pin;save(K.prefs,prefs);closeAll();return}const p=prompt('Set a 4–6 digit PIN');if(!/^\d{4,6}$/.test(p||''))return alert('Use 4 to 6 digits.');prefs.pin=p;save(K.prefs,prefs);closeAll();lock()}
