function showPrefs(){const theme=prefs.theme||'#7255e8',name=esc(prefs.name||'');detail('Preferences',`<div class="detail-section"><label>Your name <input id="profile-name" maxlength="24" placeholder="How should we greet you?" value="${name}"></label><button class="detail-add" id="save-profile">Save profile</button><label>Theme color <input id="theme-color" type="color" value="${theme}"></label><div class="theme-presets"><button data-theme="#7255e8" style="background:#7255e8"></button><button data-theme="#147dca" style="background:#147dca"></button><button data-theme="#14946b" style="background:#14946b"></button><button data-theme="#dc5a79" style="background:#dc5a79"></button><button data-theme="#df7a24" style="background:#df7a24"></button></div><button class="pref-button" id="dark-toggle">${prefs.dark?'☀ Use light mode':'◐ Use dark mode'}</button><button class="pref-button" id="reminder-toggle">${prefs.reminder?'✓ Daily reminder enabled':'♧ Enable daily reminder'}</button><button class="pref-button" id="pin-toggle">${prefs.pin?'Change / remove PIN':'Set app PIN'}</button></div>`);$('save-profile').onclick=()=>{prefs.name=$('profile-name').value.trim();save(K.prefs,prefs);renderGreeting();closeAll()};const setTheme=value=>{prefs.theme=value;applyPrefs();save(K.prefs,prefs)};$('theme-color').oninput=e=>setTheme(e.target.value);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{setTheme(b.dataset.theme);$('theme-color').value=b.dataset.theme});$('dark-toggle').onclick=()=>{prefs.dark=!prefs.dark;applyPrefs();showPrefs()};$('reminder-toggle').onclick=async()=>{if(!('Notification'in window))return alert('Notifications are not supported by this browser.');if(Notification.permission==='default')await Notification.requestPermission();prefs.reminder=Notification.permission==='granted';save(K.prefs,prefs);showPrefs()};$('pin-toggle').onclick=()=>setPin()}
