function avatarSvg(choice){const colors={violet:['#e9e2ff','#7255e8'],blue:['#dceeff','#147dca'],green:['#dcf5ec','#14946b'],rose:['#ffe2e9','#dc5a79'],orange:['#ffe9d7','#df7a24'],navy:['#e0e5f8','#344a93']},c=colors[choice]||colors.violet;return`data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="50" fill="${c[0]}"/><circle cx="50" cy="39" r="18" fill="${c[1]}"/><path d="M18 91c4-22 18-33 32-33s28 11 32 33" fill="${c[1]}"/></svg>`)}`}
function renderAvatar(){const image=$('profile-avatar'),fallback=$('avatar-fallback');image.src=prefs.avatar||avatarSvg(prefs.avatarChoice);image.classList.remove('hidden');fallback.classList.add('hidden')}
function renderGreeting(){const name=(prefs.name||'').trim();$('home-greeting').textContent=name?`Hi ${name}!`:'Hi there!';renderAvatar()}
function storeAvatar(file){if(!file||!file.type.startsWith('image/'))return alert('Please choose an image file.');const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const size=Math.min(220,Math.max(img.width,img.height)),scale=size/Math.max(img.width,img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);prefs.avatar=canvas.toDataURL('image/jpeg',.8);save(K.prefs,prefs);renderGreeting();showPrefs()};img.src=reader.result};reader.readAsDataURL(file)}
function showPrefs(){const theme=prefs.theme||'#7255e8',name=esc(prefs.name||''),picture=prefs.avatar||'';detail('Preferences',`<div class="detail-section"><label>Your name <input id="profile-name" maxlength="24" placeholder="How should we greet you?" value="${name}"></label><button class="detail-add" id="save-profile">Save profile</button><div class="profile-image-row"><img src="${picture}" alt="Profile image"><label>Upload image<input class="hidden" id="profile-image-input" type="file" accept="image/*"></label>${picture?'<button id="remove-profile-image">Remove</button>':''}</div><label>Theme color <input id="theme-color" type="color" value="${theme}"></label><div class="theme-presets"><button data-theme="#7255e8" style="background:#7255e8"></button><button data-theme="#147dca" style="background:#147dca"></button><button data-theme="#14946b" style="background:#14946b"></button><button data-theme="#dc5a79" style="background:#dc5a79"></button><button data-theme="#df7a24" style="background:#df7a24"></button></div><button class="pref-button" id="dark-toggle">${prefs.dark?'☀ Use light mode':'◐ Use dark mode'}</button><button class="pref-button" id="reminder-toggle">${prefs.reminder?'✓ Daily reminder enabled':'♧ Enable daily reminder'}</button><button class="pref-button" id="pin-toggle">${prefs.pin?'Change / remove PIN':'Set app PIN'}</button></div>`);$('save-profile').onclick=()=>{prefs.name=$('profile-name').value.trim();save(K.prefs,prefs);renderGreeting();closeAll()};$('profile-image-input').onchange=e=>storeAvatar(e.target.files[0]);if($('remove-profile-image'))$('remove-profile-image').onclick=()=>{delete prefs.avatar;save(K.prefs,prefs);renderGreeting();showPrefs()};const setTheme=value=>{prefs.theme=value;applyPrefs();save(K.prefs,prefs)};$('theme-color').oninput=e=>setTheme(e.target.value);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{setTheme(b.dataset.theme);$('theme-color').value=b.dataset.theme});$('dark-toggle').onclick=()=>{prefs.dark=!prefs.dark;applyPrefs();showPrefs()};$('reminder-toggle').onclick=async()=>{if(!('Notification'in window))return alert('Notifications are not supported by this browser.');if(Notification.permission==='default')await Notification.requestPermission();prefs.reminder=Notification.permission==='granted';save(K.prefs,prefs);showPrefs()};$('pin-toggle').onclick=()=>setPin()}
renderGreeting();
document.addEventListener('click',e=>{if(e.target.closest('[data-tool]')?.dataset.tool!=='preferences')return;setTimeout(()=>{const host=$('detail-content');if(!host||$('avatar-presets'))return;const row=document.createElement('div');row.className='detail-section';row.innerHTML='<label>Choose an avatar</label><div class="avatar-presets" id="avatar-presets"><button data-avatar-choice="violet"><span class="avatar-swatch violet"></span></button><button data-avatar-choice="blue"><span class="avatar-swatch blue"></span></button><button data-avatar-choice="green"><span class="avatar-swatch green"></span></button><button data-avatar-choice="rose"><span class="avatar-swatch rose"></span></button><button data-avatar-choice="orange"><span class="avatar-swatch orange"></span></button><button data-avatar-choice="navy"><span class="avatar-swatch navy"></span></button></div>';host.prepend(row);row.querySelectorAll('[data-avatar-choice]').forEach(button=>button.onclick=()=>{prefs.avatarChoice=button.dataset.avatarChoice;delete prefs.avatar;save(K.prefs,prefs);renderGreeting();showPrefs()})},0)});
const monthStart=new Date();monthStart.setDate(1);$('custom-start').value=localKey(monthStart);$('custom-end').value=localKey(new Date());
function labelCustomRange(){if(range==='custom'){$('overview-caption').textContent='Your selected date range';$('chart-subtitle').textContent='Daily spending for selected range'}}
document.querySelectorAll('.range-tab').forEach(button=>button.addEventListener('click',()=>{const isCustom=button.dataset.range==='custom';$('custom-range').classList.toggle('hidden',!isCustom);if(isCustom)labelCustomRange()}));
$('apply-custom-range').onclick=()=>{const start=$('custom-start').value,end=$('custom-end').value;if(!start||!end||start>end)return alert('Choose a valid start and end date.');customStart=start;customEnd=end;range='custom';document.querySelector('.range-tab.active').classList.remove('active');document.querySelector('[data-range="custom"]').classList.add('active');visibleCount=5;render();labelCustomRange()};
function showFeedback(){detail('Send feedback','<div class="detail-section"><p class="feedback-copy">Tell us what would make Spendly better. Your feedback stays on this device.</p><label>Your feedback<textarea id="feedback-text" maxlength="500" placeholder="Share an idea, issue, or suggestion..."></textarea></label><button class="detail-add" id="submit-feedback">Save feedback</button></div>');$('submit-feedback').onclick=()=>{const message=$('feedback-text').value.trim();if(!message)return;const list=prefs.feedback||[];list.push({message,date:new Date().toISOString()});prefs.feedback=list;save(K.prefs,prefs);alert('Thanks — your feedback was saved.');closeAll()}}
document.addEventListener('click',e=>{if(e.target.closest('[data-tool]')?.dataset.tool!=='feedback')return;e.preventDefault();e.stopImmediatePropagation();showFeedback()},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-tool]')?.dataset.tool!=='preferences')return;setTimeout(()=>{const preview=document.querySelector('.profile-image-row img');if(preview&&!preview.getAttribute('src'))preview.src=avatarSvg(prefs.avatarChoice)},0)},true);
new MutationObserver(()=>{const preview=document.querySelector('.profile-image-row img');if(preview&&!preview.getAttribute('src'))preview.src=avatarSvg(prefs.avatarChoice)}).observe($('detail-content'),{childList:true,subtree:true});
function injectFingerprintControl(){const host=$('detail-content');if(!$('profile-name')||$('fingerprint-control')||!window.Android)return;const enabled=window.Android.isFingerprintEnabled();const button=document.createElement('button');button.id='fingerprint-control';button.className='pref-button';button.textContent=enabled?'◉ Disable fingerprint unlock':'◉ Enable fingerprint unlock';button.onclick=()=>{if(window.Android.isFingerprintEnabled()){window.Android.disableFingerprint();prefs.fingerprint=false;save(K.prefs,prefs);showPrefs()}else window.Android.enableFingerprint()};host.append(button)}

function cloudBackup(){return JSON.stringify({expenses,categories,budget,catBudgets,recurring,goals,prefs})}
function scheduleCloudBackup(){if(!window.Android||!prefs.cloudBackup||!window.Android.cloudUser())return;clearTimeout(cloudBackupTimer);cloudBackupTimer=setTimeout(()=>window.Android.backupCloud(cloudBackup()),900)}
function applyCloudBackup(raw){const d=JSON.parse(raw);expenses=d.expenses||[];categories=d.categories||initialCats;budget=d.budget||30000;catBudgets=d.catBudgets||{};recurring=d.recurring||[];goals=d.goals||[];prefs=d.prefs||{};save(K.expenses,expenses);save(K.categories,categories);localStorage.setItem(K.budget,budget);save(K.categoryBudgets,catBudgets);save(K.recurring,recurring);save(K.goals,goals);save(K.prefs,prefs);applyPrefs();renderCategoryControls();render()}
function importGoogleProfile(){try{const profile=JSON.parse(window.Android.cloudProfile()||'{}'),first=(profile.name||'').trim().split(/\s+/)[0];if(first)prefs.name=first;if(profile.photo)prefs.avatar=profile.photo;if(profile.email)prefs.email=profile.email;save(K.prefs,prefs);renderGreeting()}catch{}}
let adminUsers=[];
function renderAdminUsers(query=''){const q=query.toLowerCase().trim(),list=$('admin-user-list');list.innerHTML=adminUsers.map((user,index)=>({user,index,p:user.data.prefs||{},count:(user.data.expenses||[]).length})).filter(item=>!q||`${item.p.name||''} ${item.p.email||''} ${item.user.uid}`.toLowerCase().includes(q)).map(item=>`<article class="admin-user"><strong>${esc(item.p.name||'Unnamed user')}<small>${esc(item.p.email||item.user.uid)} · ${item.count} transactions</small></strong><button data-admin-user="${item.index}">View</button></article>`).join('')||'<small>No matching cloud users found.</small>';document.querySelectorAll('[data-admin-user]').forEach(button=>button.onclick=()=>showAdminUser(+button.dataset.adminUser))}
function showAdminDashboard(raw){try{adminUsers=JSON.parse(raw).map(item=>({...item,data:JSON.parse(item.payload)}))}catch{alert('User data could not be read.');return}const transactions=adminUsers.flatMap(user=>user.data.expenses||[]),spend=transactions.filter(x=>(x.type||'expense')==='expense').reduce((sum,x)=>sum+(+x.amount||0),0),income=transactions.filter(x=>x.type==='income').reduce((sum,x)=>sum+(+x.amount||0),0);$('admin-user-count').textContent=adminUsers.length;$('admin-transaction-count').textContent=transactions.length;$('admin-expense-total').textContent=fmt(spend);$('admin-income-total').textContent=fmt(income);$('admin-search').value='';renderAdminUsers();$('admin-panel').classList.remove('hidden')}
function showAdminUser(index){const user=adminUsers[index],data=user.data,p=data.prefs||{},transactions=(data.expenses||[]).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,50);detail(p.name||'User details',`<div class="detail-section"><div class="detail-row"><strong>${esc(p.email||user.uid)}<small>${transactions.length} recent transactions · Budget ${fmt(data.budget||0)}</small></strong></div>${transactions.map(x=>`<div class="detail-row"><span>${esc(x.category||'Other')}</span><strong>${esc(x.note||x.category||'Transaction')}<small>${esc(x.date||'')}</small></strong><b>${x.type==='income'?'+':'−'}${fmt(+x.amount||0)}</b></div>`).join('')||'<small>No transactions found.</small>'}</div>`)}
window.onCloudResult=result=>{if(result.action==='admin'){if(result.success)showAdminDashboard(result.payload);else alert(result.message);return}if(result.action==='status'){const signedIn=!!(result.success&&window.Android&&window.Android.cloudUser());prefs.cloudBackup=signedIn;save(K.prefs,prefs);if(signedIn){importGoogleProfile();window.Android.restoreCloud()}else if(result.message==='Signed out')alert('You are signed out. Your data remains safely stored on this phone.');showData();return}if(result.action==='restore'){if(result.success){if(confirm('Cloud backup found. Replace the current data on this phone?')){try{applyCloudBackup(result.payload);alert('Cloud data restored.')}catch{alert('Cloud backup could not be read.')}}}else if(result.message.startsWith('No cloud backup'))window.Android.backupCloud(cloudBackup());else alert(result.message);return}if(result.action!=='backup')alert(result.message)}
function showData(){const nativeCloud=!!window.Android;const email=nativeCloud&&window.Android.cloudUser()?window.Android.cloudUser():'',admin=!!(email&&window.Android.isAdmin&&window.Android.isAdmin());detail('Export & backup',`<div class="detail-section">${nativeCloud?`<div class="cloud-card"><strong>${email?'Backup enabled':'Cloud backup'}</strong><small>${email?'Signed in as '+esc(email)+'. Changes are automatically backed up to your private Firebase account.':'Your expenses stay only on this phone until you choose Google sign-in.'}</small>${email?'<button class="pref-button" id="cloud-backup">Back up now</button><button class="pref-button" id="cloud-restore">Restore from cloud</button>'+ (admin?'<button class="pref-button" id="admin-dashboard">Admin dashboard</button>':'') +'<button class="pref-button" id="cloud-signout">Sign out of Google</button>':'<button class="detail-add" id="cloud-signin">Enable backup with Google</button>'}</div>`:'<small>Cloud backup is available in the Android app.</small>'}<button class="pref-button" id="export-data">Download backup (.json)</button><button class="pref-button" id="import-data">Import backup</button><small>Imports replace all current local data.</small></div>`);$('export-data').onclick=()=>{const blob=new Blob([cloudBackup()],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='spendly-backup.json';a.click();URL.revokeObjectURL(a.href)};$('import-data').onclick=()=>$('import-file').click();if(nativeCloud){if(email){$('cloud-backup').onclick=()=>window.Android.backupCloud(cloudBackup());$('cloud-restore').onclick=()=>window.Android.restoreCloud();$('cloud-signout').onclick=()=>window.Android.signOutCloud();if(admin)$('admin-dashboard').onclick=()=>window.Android.getAdminData()}else $('cloud-signin').onclick=()=>window.Android.googleSignIn()}}
window.onFingerprintResult=(enabled,message)=>{prefs.fingerprint=enabled;save(K.prefs,prefs);alert(message);showPrefs()};
window.onNativeFingerprintUnlock=()=>{$('lock-screen').classList.add('hidden');$('unlock-pin').value='';$('lock-message').textContent=''};
window.onNativeFingerprintFallback=()=>{$('lock-screen').classList.remove('hidden');$('lock-message').textContent='Fingerprint was not used. Enter your PIN to unlock.'};
new MutationObserver(injectFingerprintControl).observe($('detail-content'),{childList:true,subtree:true});
$('forgot-pin').onclick=()=>{if(!confirm('Reset your PIN? Your expenses and settings will stay safe on this phone.'))return;delete prefs.pin;save(K.prefs,prefs);$('unlock-pin').value='';$('lock-message').textContent='PIN removed. You can set a new one later in Preferences.';$('lock-screen').classList.add('hidden')};
let toastTimer;window.alert=message=>{const toast=$('app-toast');toast.textContent=message;toast.classList.remove('hidden');requestAnimationFrame(()=>toast.classList.add('show'));clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.classList.remove('show');setTimeout(()=>toast.classList.add('hidden'),220)},3200)};
$('close-admin-panel').onclick=()=>$('admin-panel').classList.add('hidden');$('admin-search').oninput=e=>renderAdminUsers(e.target.value);
function askDialog({title='Heads up',message='',fields=[],confirmText='Continue',danger=false}){return new Promise(resolve=>{const dialog=$('app-dialog'),backdrop=$('dialog-backdrop'),form=$('dialog-form'),close=value=>{dialog.classList.add('hidden');backdrop.classList.add('hidden');form.onsubmit=null;$('dialog-cancel').onclick=null;resolve(value)};$('dialog-title').textContent=title;$('dialog-message').textContent=message;$('dialog-eyebrow').textContent=danger?'PLEASE CONFIRM':'SPENDLY';$('dialog-icon').textContent=danger?'!':fields.length?'✦':'i';$('dialog-confirm').textContent=confirmText;$('dialog-cancel').textContent=fields.length?'Cancel':'Not now';dialog.classList.toggle('danger',danger);$('dialog-fields').innerHTML=fields.map((f,i)=>`<label>${esc(f.label)}<input data-dialog-field="${i}" type="${f.type||'text'}" value="${esc(f.value||'')}" placeholder="${esc(f.placeholder||'')}" ${f.required?'required':''}></label>`).join('');dialog.classList.remove('hidden');backdrop.classList.remove('hidden');$('dialog-cancel').onclick=()=>close(null);backdrop.onclick=()=>close(null);form.onsubmit=e=>{e.preventDefault();close(fields.length?fields.map((_,i)=>document.querySelector(`[data-dialog-field="${i}"]`).value):true)};setTimeout(()=>document.querySelector('[data-dialog-field]')?.focus(),30)})}
function renameCat(old){askDialog({title:'Rename category',message:'Choose a clear name for this category.',fields:[{label:'Category name',value:old,required:true}],confirmText:'Save name'}).then(values=>{const name=values?.[0]?.trim().replace(/[^a-zA-Z0-9 &-]/g,'');if(!name||name===old)return;if(categories.some(c=>c.name.toLowerCase()===name.toLowerCase()))return alert('That category already exists.');categories=categories.map(c=>c.name===old?{...c,name}:c);expenses=expenses.map(x=>x.category===old?{...x,category:name}:x);if(chosenCategory===old)chosenCategory=name;if(filter===old)filter=name;save(K.categories,categories);save(K.expenses,expenses);renderCategoryControls();render()})}
function removeCat(name){if(categories.length===1)return alert('Keep at least one category.');askDialog({title:'Delete category?',message:`“${name}” will be removed. Existing transactions will be kept.`,confirmText:'Delete category',danger:true}).then(ok=>{if(!ok)return;categories=categories.filter(c=>c.name!==name);save(K.categories,categories);renderCategoryControls();render()})}
function showRecurring(){detail('Recurring expenses',`<div class="detail-section"><button class="detail-add" id="add-recurring">+ Add recurring item</button>${recurring.map(r=>`<div class="detail-row"><span>${icon(r.category)}</span><strong>${esc(r.note||r.category)}<small>${fmt(r.amount)} · day ${r.day}</small></strong><button class="danger" data-del-rec="${r.id}">Delete</button></div>`).join('')||'<small>No recurring items yet.</small>'}</div>`);$('add-recurring').onclick=()=>askDialog({title:'Add recurring expense',message:'This item will be added automatically each month.',fields:[{label:'Name',placeholder:'e.g. House rent',required:true},{label:'Amount',type:'number',placeholder:'0',required:true},{label:'Day of month',type:'number',value:'1',required:true}],confirmText:'Add item'}).then(values=>{const[note,amount,day]=values||[];if(!note||!(+amount)||+day<1||+day>28)return;recurring.push({id:crypto.randomUUID(),note:note.trim(),amount:+amount,day:+day,category:chosenCategory||categories[0].name});save(K.recurring,recurring);showRecurring()});document.querySelectorAll('[data-del-rec]').forEach(b=>b.onclick=()=>askDialog({title:'Delete recurring item?',message:'This cannot be undone.',confirmText:'Delete',danger:true}).then(ok=>{if(ok){recurring=recurring.filter(r=>r.id!==b.dataset.delRec);save(K.recurring,recurring);showRecurring()}}))}
function showGoals(){detail('Savings goals',`<div class="detail-section"><button class="detail-add" id="add-goal">+ Add savings goal</button>${goals.map(g=>`<div class="detail-row"><span>◎</span><strong>${esc(g.name)}<small>${fmt(g.saved)} of ${fmt(g.target)}</small></strong><button data-add-goal="${g.id}">+ Add</button><button class="danger" data-del-goal="${g.id}">×</button></div>`).join('')||'<small>Create a goal for your next big purchase.</small>'}</div>`);$('add-goal').onclick=()=>askDialog({title:'Create savings goal',message:'Give your goal a name and target amount.',fields:[{label:'Goal name',required:true},{label:'Target amount',type:'number',placeholder:'0',required:true}],confirmText:'Create goal'}).then(values=>{const[name,target]=values||[];if(!name||!(+target))return;goals.push({id:crypto.randomUUID(),name:name.trim(),target:+target,saved:0});save(K.goals,goals);showGoals()});document.querySelectorAll('[data-add-goal]').forEach(b=>b.onclick=()=>askDialog({title:'Add savings',message:'How much would you like to add?',fields:[{label:'Amount',type:'number',placeholder:'0',required:true}],confirmText:'Add savings'}).then(values=>{const value=+values?.[0];if(value){goals=goals.map(g=>g.id===b.dataset.addGoal?{...g,saved:g.saved+value}:g);save(K.goals,goals);showGoals()}}));document.querySelectorAll('[data-del-goal]').forEach(b=>b.onclick=()=>askDialog({title:'Delete savings goal?',message:'Your saved progress will be removed.',confirmText:'Delete goal',danger:true}).then(ok=>{if(ok){goals=goals.filter(g=>g.id!==b.dataset.delGoal);save(K.goals,goals);showGoals()}}))}
function setPin(){if(prefs.pin){askDialog({title:'Remove app PIN?',message:'You can set a new PIN later in Preferences.',confirmText:'Remove PIN',danger:true}).then(ok=>{if(ok){delete prefs.pin;save(K.prefs,prefs);closeAll()}});return}askDialog({title:'Set app PIN',message:'Use 4 to 6 digits to protect your spending data.',fields:[{label:'PIN',type:'password',placeholder:'4–6 digits',required:true}],confirmText:'Set PIN'}).then(values=>{const pin=values?.[0];if(!pin)return;if(!/^\d{4,6}$/.test(pin))return alert('Use 4 to 6 digits.');prefs.pin=pin;save(K.prefs,prefs);closeAll();lock()})}
$('delete-expense').onclick=()=>{if(!editingId)return;askDialog({title:'Delete transaction?',message:'This transaction will be permanently removed.',confirmText:'Delete transaction',danger:true}).then(ok=>{if(ok){expenses=expenses.filter(x=>x.id!==editingId);save(K.expenses,expenses);closeAll();render()}})};
$('forgot-pin').onclick=()=>askDialog({title:'Reset your PIN?',message:'Your expenses and settings will remain safe on this phone.',confirmText:'Reset PIN',danger:true}).then(ok=>{if(ok){delete prefs.pin;save(K.prefs,prefs);$('unlock-pin').value='';$('lock-message').textContent='PIN removed. You can set a new one later in Preferences.';$('lock-screen').classList.add('hidden')}});
$('import-file').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{let data;try{data=JSON.parse(reader.result)}catch{return alert('That backup file is not valid.')}askDialog({title:'Replace current data?',message:'Your current expenses, budgets, and settings will be replaced with this backup.',confirmText:'Replace data',danger:true}).then(ok=>{if(!ok)return;expenses=data.expenses||[];categories=data.categories||initialCats;budget=data.budget||30000;catBudgets=data.catBudgets||{};recurring=data.recurring||[];goals=data.goals||[];prefs=data.prefs||{};save(K.expenses,expenses);save(K.categories,categories);localStorage.setItem(K.budget,budget);save(K.categoryBudgets,catBudgets);save(K.recurring,recurring);save(K.goals,goals);save(K.prefs,prefs);applyPrefs();renderCategoryControls();closeAll();render()})};reader.readAsText(file)};
window.onCloudResult=async result=>{if(result.action==='admin'){if(result.success)showAdminDashboard(result.payload);else alert(result.message);return}if(result.action==='status'){const signedIn=!!(result.success&&window.Android&&window.Android.cloudUser());prefs.cloudBackup=signedIn;save(K.prefs,prefs);if(signedIn){importGoogleProfile();window.Android.restoreCloud()}else if(result.message==='Signed out')alert('You are signed out. Your data remains safely stored on this phone.');showData();return}if(result.action==='restore'){if(result.success){if(await askDialog({title:'Restore cloud backup?',message:'This will replace the data currently stored on this phone.',confirmText:'Restore data',danger:true})){try{applyCloudBackup(result.payload);alert('Cloud data restored.')}catch{alert('Cloud data could not be read.')}}}else if(result.message.startsWith('No cloud backup'))window.Android.backupCloud(cloudBackup());else alert(result.message);return}if(result.action!=='backup')alert(result.message)};
document.addEventListener('click',async event=>{if(!event.target.closest('#reminder-toggle'))return;event.preventDefault();event.stopImmediatePropagation();if(window.Android?.enableDailyReminder){window.Android.enableDailyReminder();return}if(!('Notification'in window))return alert('Daily reminders are available in the Spendly Android app.');if(Notification.permission==='default')await Notification.requestPermission();prefs.reminder=Notification.permission==='granted';save(K.prefs,prefs);showPrefs()},true);
window.onReminderResult=(enabled,message)=>{prefs.reminder=enabled;save(K.prefs,prefs);alert(message);showPrefs()};
const reminderToday=localKey(new Date());if(prefs.reminder&&prefs.lastReminder!==reminderToday&&window.Android?.showDailyReminder){window.Android.showDailyReminder();prefs.lastReminder=reminderToday;save(K.prefs,prefs)};
let categoryFilters=new Set();
function matches(x){return(!categoryFilters.size||categoryFilters.has(x.category))&&(!query||`${x.category} ${x.note||''} ${x.payment||''}`.toLowerCase().includes(query))}
function renderCategoryControls(){if(!categories.some(c=>c.name===chosenCategory))chosenCategory=categories[0]?.name||'';categoryFilters=new Set([...categoryFilters].filter(name=>categories.some(c=>c.name===name)));$('category-picker').innerHTML=categories.map(c=>`<button type="button" data-cat="${esc(c.name)}" class="${c.name===chosenCategory?'chosen':''}">${c.icon}<span>${esc(c.name)}</span></button>`).join('');document.querySelectorAll('[data-cat]').forEach(button=>button.onclick=()=>{chosenCategory=button.dataset.cat;renderCategoryControls()});const button=$('category-filter'),menu=$('category-filter-menu'),selected=[...categoryFilters];button.textContent=!selected.length?'All categories':selected.length===1?selected[0]:`${selected.length} categories`;button.setAttribute('aria-expanded','false');menu.classList.add('hidden');menu.innerHTML=`<label><input data-category-all type="checkbox" ${selected.length?'':'checked'}> All categories</label>${categories.map(c=>`<label><input data-category-filter="${esc(c.name)}" type="checkbox" ${categoryFilters.has(c.name)?'checked':''}> ${c.icon} ${esc(c.name)}</label>`).join('')}`;button.onclick=event=>{event.stopPropagation();const open=menu.classList.toggle('hidden');button.setAttribute('aria-expanded',String(!open))};menu.querySelector('[data-category-all]').onchange=event=>{if(event.target.checked)categoryFilters.clear();renderCategoryControls();render()};menu.querySelectorAll('[data-category-filter]').forEach(input=>input.onchange=()=>{if(input.checked)categoryFilters.add(input.dataset.categoryFilter);else categoryFilters.delete(input.dataset.categoryFilter);renderCategoryControls();render()});renderCategoryList()}
document.addEventListener('click',event=>{if(!event.target.closest('.filter-label'))$('category-filter-menu')?.classList.add('hidden')});
renderCategoryControls();render();
function exportFile(filename,mimeType,content){if(window.Android?.downloadBackup){window.Android.downloadBackup(filename,mimeType,content);return}const blob=new Blob([content],{type:mimeType}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),100);alert(`${filename} downloaded.`)}
function transactionsCsv(){const escapeCsv=value=>`"${String(value??'').replace(/"/g,'""')}"`,headers=['Date','Type','Category','Note','Payment method','Amount'];return[headers,...expenses.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(item=>[item.date,item.type||'expense',item.category,item.note||'',item.payment||'',item.amount].map(escapeCsv))].map(row=>row.join(',')).join('\n')}
function showData(){const nativeCloud=!!window.Android,email=nativeCloud&&window.Android.cloudUser()?window.Android.cloudUser():'',admin=!!(email&&window.Android.isAdmin&&window.Android.isAdmin());detail('Export & backup',`<div class="detail-section">${nativeCloud?`<div class="cloud-card"><strong>${email?'Backup enabled':'Cloud backup'}</strong><small>${email?'Signed in as '+esc(email)+'. Changes are automatically backed up to your private Firebase account.':'Your expenses stay only on this phone until you choose Google sign-in.'}</small>${email?'<button class="pref-button" id="cloud-backup">Back up now</button><button class="pref-button" id="cloud-restore">Restore from cloud</button>' +(admin?'<button class="pref-button" id="admin-dashboard">Admin dashboard</button>':'')+'<button class="pref-button" id="cloud-signout">Sign out of Google</button>':'<button class="detail-add" id="cloud-signin">Enable backup with Google</button>'}</div>`:'<small>Cloud backup is available in the Android app.</small>'}<button class="pref-button" id="export-json">Download full backup (.json)</button><button class="pref-button" id="export-csv">Download transactions (.csv)</button><button class="pref-button" id="import-data">Import backup</button><small>JSON includes all app settings. CSV is ideal for spreadsheets.</small></div>`);$('export-json').onclick=()=>exportFile('spendly-backup.json','application/json',cloudBackup());$('export-csv').onclick=()=>exportFile('spendly-transactions.csv','text/csv;charset=utf-8',transactionsCsv());$('import-data').onclick=()=>$('import-file').click();if(nativeCloud){if(email){$('cloud-backup').onclick=()=>window.Android.backupCloud(cloudBackup());$('cloud-restore').onclick=()=>window.Android.restoreCloud();$('cloud-signout').onclick=()=>window.Android.signOutCloud();if(admin)$('admin-dashboard').onclick=()=>window.Android.getAdminData()}else $('cloud-signin').onclick=()=>window.Android.googleSignIn()}}
window.onBackupSaved=success=>alert(success?'Backup saved successfully.':'Backup could not be saved.');
window.handleAppBack=()=>{const dialog=$('app-dialog');if(dialog&&!dialog.classList.contains('hidden')){$('dialog-cancel').click();return true}const filterMenu=$('category-filter-menu');if(filterMenu&&!filterMenu.classList.contains('hidden')){filterMenu.classList.add('hidden');$('category-filter')?.setAttribute('aria-expanded','false');return true}const admin=$('admin-panel');if(admin&&!admin.classList.contains('hidden')){admin.classList.add('hidden');return true}const sheets=['expense-modal','budget-modal','category-modal','tools-modal','tool-detail'];if(sheets.some(id=>!$(id).classList.contains('hidden'))){closeAll();return true}return false};
